data class Discipline(val id:Long=System.currentTimeMillis(),val name:String,val color:Int)
data class ScheduleSlot(val id:Long=System.nanoTime(),val disciplineId:Long,val weekday:Int,val start:String,val end:String)
data class StudyLog(val id:Long=System.nanoTime(),val disciplineId:Long,val date:String,val minutes:Int)
private val Blue=Color(0xFF087DF0);private val Navy=Color(0xFF112544);private val Bg=Color(0xFFF5F8FD);private val Red=Color(0xFFFF416C)
private val palette=listOf(0xFF1684EA.toInt(),0xFFFF426D.toInt(),0xFFF9B51A.toInt(),0xFF10B981.toInt(),0xFF7C5CE7.toInt(),0xFFFF7A32.toInt())
private val dayNames=listOf("Seg","Ter","Qua","Qui","Sex","Sáb","Dom")
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Blue,background=Bg)){App()}}}}
@Composable private fun App(){var tab by remember{mutableIntStateOf(0)};var disciplines by remember{mutableStateOf(listOf<Discipline>())};var slots by remember{mutableStateOf(listOf<ScheduleSlot>())};var logs by remember{mutableStateOf(listOf<StudyLog>())};var chosen by remember{mutableStateOf<Discipline?>(null)};var newDiscipline by remember{mutableStateOf(false)};var editSlot by remember{mutableStateOf<ScheduleSlot?>(null)}
 Scaffold(containerColor=Bg,bottomBar={NavigationBar(containerColor=Color.White){listOf("Disciplinas" to Icons.Default.School,"Agenda" to Icons.Default.CalendarMonth,"Cronómetro" to Icons.Default.Timer,"Análise" to Icons.Default.BarChart,"Definições" to Icons.Default.Settings).forEachIndexed{i,p->NavigationBarItem(tab==i,{tab=i},{Icon(p.second,null)},{Text(p.first,fontSize=9.sp)})}}},floatingActionButton={if(tab==0&&chosen==null)FloatingActionButton({newDiscipline=true},containerColor=Blue){Icon(Icons.Default.Add,null,tint=Color.White)}}){pad->Box(Modifier.padding(pad)){when(tab){0->if(chosen==null)Disciplines(disciplines,slots,logs,{chosen=it})else DisciplineDetail(chosen!!,slots.filter{it.disciplineId==chosen!!.id},logs.filter{it.disciplineId==chosen!!.id},{chosen=null},{slot->slots=slots+slot},{slot->slots=slots.filterNot{it.id==slot.id}},{d->disciplines=disciplines.filterNot{it.id==d.id};slots=slots.filterNot{it.disciplineId==d.id};logs=logs.filterNot{it.disciplineId==d.id};chosen=null});1->Agenda(disciplines,slots,{editSlot=it});2->TimerPage(disciplines){id,m->logs=logs+StudyLog(disciplineId=id,date=LocalDate.now().toString(),minutes=m)};3->Analysis(disciplines,logs);else->SettingsPage()}}}
 if(newDiscipline)DisciplineDialog({newDiscipline=false}){name->disciplines=disciplines+Discipline(name=name,color=palette[disciplines.size%palette.size]);newDiscipline=false}
 if(editSlot!=null||chosen!=null&&false){}
 chosen?.let{d->if(editSlot==null&&tab==0){}}
}
@Composable private fun Top(title:String,back:(()->Unit)?=null){Row(Modifier.fillMaxWidth().background(Color.White).padding(18.dp),verticalAlignment=Alignment.CenterVertically){if(back!=null)IconButton(back){Icon(Icons.Default.ArrowBack,null)};Text(title,Modifier.weight(1f),fontSize=25.sp,fontWeight=FontWeight.Bold,color=Navy);Icon(Icons.Default.Search,null,tint=Navy)}}
@Composable private fun Disciplines(ds:List<Discipline>,slots:List<ScheduleSlot>,logs:List<StudyLog>,open:(Discipline)->Unit){Column{Top("Disciplinas");LazyColumn{items(ds,key={it.id}){d->Card(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=6.dp).clickable{open(d)},colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(16.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Surface(Modifier.size(52.dp),shape=RoundedCornerShape(14.dp),color=Color(d.color)){Icon(Icons.Default.School,null,tint=Color.White,modifier=Modifier.padding(12.dp))};Column(Modifier.padding(start=12.dp).weight(1f)){Text(d.name,fontWeight=FontWeight.Bold);Text("${label(logs.filter{it.disciplineId==d.id}.sumOf{it.minutes})} estudados",fontSize=12.sp);Text("${slots.count{it.disciplineId==d.id}} programações",fontSize=12.sp)};Icon(Icons.Default.ChevronRight,null)}}};item{Spacer(Modifier.height(90.dp))}}}}
@Composable private fun DisciplineDetail(d:Discipline,slots:List<ScheduleSlot>,logs:List<StudyLog>,back:()->Unit,addSlot:(ScheduleSlot)->Unit,deleteSlot:(ScheduleSlot)->Unit,deleteDiscipline:(Discipline)->Unit){var showSchedule by remember{mutableStateOf(false)};Column{Top(d.name,back);Card(Modifier.fillMaxWidth().padding(14.dp),colors=CardDefaults.cardColors(Color(d.color))){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.School,null,tint=Color.White,modifier=Modifier.size(44.dp));Column(Modifier.padding(start=14.dp)){Text(d.name,color=Color.White,fontSize=21.sp,fontWeight=FontWeight.Bold);Text("${label(logs.sumOf{it.minutes})} estudados",color=Color.White)}}};Text("Programações",Modifier.padding(16.dp,8.dp),fontWeight=FontWeight.Bold);LazyColumn(Modifier.weight(1f)){items(slots,key={it.id}){s->Card(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=5.dp),colors=CardDefaults.cardColors(Color.White)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Alarm,null,tint=Color(d.color));Column(Modifier.padding(start=12.dp).weight(1f)){Text(dayNames[s.weekday-1],fontWeight=FontWeight.Bold);Text("${s.start} - ${s.end}")};IconButton({deleteSlot(s)}){Icon(Icons.Default.Delete,null,tint=Red)}}}}};OutlinedButton({showSchedule=true},Modifier.fillMaxWidth().padding(14.dp)){Icon(Icons.Default.Add,null);Text("  Adicionar programação")};Button({deleteDiscipline(d)},Modifier.fillMaxWidth().padding(horizontal=14.dp),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFFFFE9EE),contentColor=Red)){Text("Eliminar disciplina")}}
 if(showSchedule)ScheduleDialog(d,{showSchedule=false}){slot->addSlot(slot);showSchedule=false}}
@Composable private fun Agenda(ds:List<Discipline>,slots:List<ScheduleSlot>,open:(ScheduleSlot)->Unit){var mode by remember{mutableIntStateOf(1)};var offset by remember{mutableIntStateOf(0)};val monday=LocalDate.now().minusDays((LocalDate.now().dayOfWeek.value-1).toLong()).plusWeeks(offset.toLong());Column{Top("Agenda");Row(Modifier.fillMaxWidth().padding(12.dp)){listOf("Dia","Semana","Mês").forEachIndexed{i,x->Button({mode=i},Modifier.weight(1f).padding(2.dp),colors=ButtonDefaults.buttonColors(containerColor=if(mode==i)Blue else Color(0xFFE8EEF7),contentColor=if(mode==i)Color.White else Navy)){Text(x)}}};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton({offset--}){Icon(Icons.Default.ChevronLeft,null)};Text("${monday.format(DateTimeFormatter.ofPattern("d"))} – ${monday.plusDays(6).format(DateTimeFormatter.ofPattern("d 'de' MMMM 'de' yyyy"))}",Modifier.weight(1f),textAlign=TextAlign.Center,fontWeight=FontWeight.Bold);IconButton({offset++}){Icon(Icons.Default.ChevronRight,null)}};if(mode==1)WeekGrid(ds,slots,monday,open)else DayList(ds,slots,if(mode==0)LocalDate.now().dayOfWeek.value else 1,open)}}
@Composable private fun WeekGrid(ds:List<Discipline>,slots:List<ScheduleSlot>,monday:LocalDate,open:(ScheduleSlot)->Unit){Row(Modifier.fillMaxSize().padding(8.dp)){Column(Modifier.width(38.dp).padding(top=48.dp)){listOf("08","10","12","14","16","18","20").forEach{Text("$it:00",fontSize=9.sp,modifier=Modifier.height(48.dp))}};(1..7).forEach{day->Column(Modifier.weight(1f)){Text(dayNames[day-1],Modifier.fillMaxWidth(),textAlign=TextAlign.Center,fontSize=10.sp);Text(monday.plusDays((day-1).toLong()).dayOfMonth.toString(),Modifier.fillMaxWidth(),textAlign=TextAlign.Center,fontWeight=FontWeight.Bold);slots.filter{it.weekday==day}.sortedBy{it.start}.forEach{s->val d=ds.firstOrNull{it.id==s.disciplineId};Card(Modifier.fillMaxWidth().padding(1.dp).clickable{open(s)},colors=CardDefaults.cardColors(Color(d?.color?:palette[0]).copy(alpha=.22f))){Text((d?.name?:"").take(4)+"\n${s.start}",fontSize=8.sp,modifier=Modifier.padding(3.dp))}}}}}
@Composable private fun DayList(ds:List<Discipline>,slots:List<ScheduleSlot>,day:Int,open:(ScheduleSlot)->Unit){LazyColumn{items(slots.filter{it.weekday==day}.sortedBy{it.start}){s->val d=ds.firstOrNull{it.id==s.disciplineId};Card(Modifier.fillMaxWidth().padding(12.dp,5.dp).clickable{open(s)},colors=CardDefaults.cardColors(Color.White)){Row(Modifier.padding(14.dp)){Text("${s.start}\n${s.end}",Modifier.width(80.dp));Text(d?.name?:"Disciplina",fontWeight=FontWeight.Bold)}}}}}
@Composable private fun TimerPage(ds:List<Discipline>,finish:(Long,Int)->Unit){var selected by remember{mutableStateOf(ds.firstOrNull())};var sec by remember{mutableLongStateOf(0)};var running by remember{mutableStateOf(false)};LaunchedEffect(running){while(running){delay(1000);sec++}};Column(horizontalAlignment=Alignment.CenterHorizontally){Top("Cronómetro");Text(selected?.name?:"Selecione uma disciplina",Modifier.padding(20.dp),fontWeight=FontWeight.Bold);Text("%02d:%02d:%02d".format(sec/3600,(sec/60)%60,sec%60),fontSize=44.sp,fontWeight=FontWeight.Bold,color=Navy);Row(Modifier.padding(20.dp)){Button({running=!running}){Text(if(running)"Pausar" else "Iniciar")};Spacer(Modifier.width(10.dp));OutlinedButton({selected?.let{finish(it.id,(sec/60).toInt().coerceAtLeast(1))};sec=0;running=false}){Text("Terminar")}};LazyColumn{items(ds){d->TextButton({selected=d}){Text(d.name)}}}}}
@Composable private fun Analysis(ds:List<Discipline>,logs:List<StudyLog>){val total=logs.sumOf{it.minutes};Column{Top("Análise");Row{Stat("Tempo total",label(total),Modifier.weight(1f));Stat("Média diária",label(total/7),Modifier.weight(1f))};Text("Tempo por disciplina",Modifier.padding(16.dp),fontWeight=FontWeight.Bold);LazyColumn{items(ds){d->val min=logs.filter{it.disciplineId==d.id}.sumOf{it.minutes};ListItem(headlineContent={Text(d.name)},supportingContent={LinearProgressIndicator(if(total==0)0f else min.toFloat()/total)},trailingContent={Text(label(min))})}}}}
@Composable private fun Stat(t:String,v:String,m:Modifier){Card(m.padding(8.dp),colors=CardDefaults.cardColors(Color.White)){Column(Modifier.padding(16.dp)){Text(t,color=Color.Gray);Text(v,fontSize=22.sp,fontWeight=FontWeight.Bold)}}}
@Composable private fun SettingsPage(){Column{Top("Definições");listOf("Alarmes de estudo","Som","Vibração","Tema escuro").forEach{var x by remember{mutableStateOf(true)};Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text(it,Modifier.weight(1f));Switch(x,{x=it})}};ListItem(headlineContent={Text("CronosEstudo")},trailingContent={Text("v1.7.0")})}}
@Composable private fun DisciplineDialog(close:()->Unit,save:(String)->Unit){var name by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Nova disciplina")},text={OutlinedTextField(name,{name=it},label={Text("Nome da disciplina")})},confirmButton={Button({if(name.isNotBlank())save(name.trim())}){Text("Guardar")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun ScheduleDialog(d:Discipline,close:()->Unit,save:(ScheduleSlot)->Unit){var day by remember{mutableIntStateOf(1)};var start by remember{mutableStateOf("18:00")};var end by remember{mutableStateOf("19:00")};AlertDialog(onDismissRequest=close,title={Text("Adicionar programação")},text={Column{Row{(1..7).forEach{i->FilterChip(day==i,{day=i},{Text(dayNames[i-1].take(1))},modifier=Modifier.weight(1f))}};OutlinedTextField(start,{start=it},label={Text("Início")});OutlinedTextField(end,{end=it},label={Text("Fim")})}},confirmButton={Button({runCatching{require(LocalTime.parse(end).isAfter(LocalTime.parse(start)));save(ScheduleSlot(disciplineId=d.id,weekday=day,start=start,end=end))}}){Text("Guardar")}},dismissButton={TextButton(close){Text("Cancelar")}})}
private fun label(m:Int)=if(m>=60)"${m/60}h ${m%60}min" else "${m}min"
